            "01",
            "-01",
            "+1",
            ".1",
            "1.",
            "1e",
            "1e+",
            "1e-",
            "1e+2.0",
            "1e+2x",
            "1e++2",
            "NaN",
            "1 ",
            " 1",
            "1\n",
            "١",
