                original.0.push(operation);
            }
            let guarded = guard(left.clone(), &original).unwrap();
            proptest::prop_assert_eq!(apply_json_patch(&left, &guarded).unwrap(), shadow);
            let (size, _) = guarded_bytes(&left, &original, true, &[]).unwrap();
