                    guarded_bytes(&left, &original, true, &costs[..=end])
                        .unwrap()
                        .0,
                    size
                );
            }
            let inverse = crate::invert_json_patch(&left, &actual).unwrap();
            json_patch::patch(&mut applied, &inverse).unwrap();
